from pathlib import Path
from hashlib import sha256
from datetime import datetime,timezone
import json,subprocess,runpy,difflib,sys,ctypes,re
R=Path.cwd();sys.path.insert(0,str(R));B=R/'verification/maintenance/gate0-tools'
def read(p):return json.loads((R/p).read_bytes())
def pin(p):
 raw=(R/p).read_bytes();return {'sha256':sha256(raw).hexdigest(),'bytes':len(raw)}
def write(p,v):(R/p).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n','utf8')
def save(p,s):
 p=R/p;old=p.read_bytes().decode('utf8').splitlines(keepends=True);new=s.splitlines(keepends=True)
 for a,b,k in difflib.SequenceMatcher(None,[v.rstrip('\r\n')for v in old],[v.rstrip('\r\n')for v in new],autojunk=False).get_matching_blocks():new[b:b+k]=old[a:a+k]
 p.write_bytes(''.join(new).encode('utf8'))
