write(B/'source-review.json',{'sources':{p:pin(p)for p in sources},'summary':'Existing MainWindow accepts an optional recorder and records only applied/rejected samples and capture errors. Overlay payload adds optional first-rejection diagnostics while keeping original conditions and coordinates; baseline function comparison covers eleven input cases with and without diagnostics. Existing overlay tick forwards decisions only when explicitly enabled by an injected recorder. Standard-library QueueHandler/QueueListener own JSONL I/O; state/performance allowlists exclude notes, chat, keys and raw OCR. Runtime Qt topLevelWidgets enumerates visible surfaces and shared page classes without reading titles; weak references retain surface numbering without extending widget lifetime. Explicit launcher alone enables recording; ordinary startup remains disabled. Replay converts recorded snapshot run_id to RunState id and alternates enabled/disabled rounds after warmup. No overlay threshold, renewal, OCR, game input, chat, or UI architecture change.','whole_program_review_complete':False})
write(B/'reuse.json',{'sources':[{'url':'https://github.com/python/cpython/blob/v3.12.14/Lib/logging/handlers.py','component':'QueueHandler and QueueListener','use':'Existing Python3.12.14 standard-library producer/listener pipeline; separate background I/O, own allowlisted JSON messages.'},{'url':'https://docs.python.org/3.12/howto/logging-cookbook.html#dealing-with-handlers-that-block','use':'Official recipe for separating handlers that can block from caller work.'},{'url':'https://doc.qt.io/qtforpython-6/PySide6/QtWidgets/QApplication.html#PySide6.QtWidgets.QApplication.topLevelWidgets','use':'Existing Qt6.11.2 visible application surfaces, not file/title counts.'}],'new_packages_or_copied_upstream_program':False,'choice':'Use mature installed standard-library/Qt facilities. A separate external telemetry backend or full tracing framework adds deployment/network/maintenance cost beyond this local Gate 0 scope.','no_personal_uploads':True})
write(B/'summary.json',{'kind':'implementation_maintenance','title':'连续体验流程与Gate 0本地记录工具','passed':True,'passed_scope':'51 targeted tests, 19 native isolated original-window checks, current visible original test window, synthetic same-input recording-path benchmark. Source-pinned optional instrumentation preserves original overlay decisions.','section_incremented':False,'completed_functional_section':472,'gate':0,'gate_passed':False,'real_sessions_completed':0,'pending':['Normal, transition/animation and resize/occlusion real game sessions of about10minutes each with private local video.','Independent video labels, update/removal latency and misattribution counts.','Actual session recording-overhead replay and impact-ranked causes.','Real static60-second, sparse-node and resize-recovery scenarios.'],'plan':'docs/decisions/2026-11-02-experience-gates.md','instructions':'docs/gate0/README.md','checks':{'count':51,'process':'verification/maintenance/gate0-tools/checks-current/process.json'},'native':{'count':19,'receipt':'verification/maintenance/gate0-tools/native-final/window.json'},'benchmark':'verification/maintenance/gate0-tools/recording-overhead.json','original_failures':['verification/maintenance/gate0-tools/first-failure.json','verification/maintenance/gate0-tools/benchmark-first-failure.json'],'private_six_unchanged':True,'private_session_data_published':False,'whole_program_or_gate_completed':False,'full_validation_rerun':False,'at_UTC':datetime.now(timezone.utc).isoformat()})
